// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        assertTrue(!success, "Non-admin should not be able to set owner");
    }
}
